const ACTIVITY_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    title: { type: Type.STRING },
    description: { type: Type.STRING },
    startTime: { type: Type.STRING },
    endTime: { type: Type.STRING },
    location: { type: Type.STRING },
    category: {
      type: Type.STRING,
      enum: [
        'sightseeing',
        'dining',
        'beach',
        'water_sports',
        'transport',
        'accommodation',
        'relaxation',
        'shopping',
        'other',
      ],
    },
    estimatedCost: { type: Type.NUMBER },
    notes: { type: Type.STRING },
  },
  required: ['title', 'description', 'startTime', 'endTime', 'location', 'category', 'estimatedCost'],
};

const DAY_ITINERARY_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    dayNumber: { type: Type.INTEGER },
    date: { type: Type.STRING },
    theme: { type: Type.STRING },
    activities: { type: Type.ARRAY, items: ACTIVITY_SCHEMA },
    estimatedDayCost: { type: Type.NUMBER },
    notes: { type: Type.STRING },
  },
  required: ['dayNumber', 'theme', 'activities', 'estimatedDayCost'],
};

