// ==========================================
// Output Validators & Normalizers
// ==========================================

const normalizeDayItinerary = (days) => {
  if (!Array.isArray(days) || days.length === 0) {
    throw new ApiError(
      502,
      'AI response did not include a valid day-wise itinerary. Please try again.'
    );
  }

  return days.map((day, idx) => {
    const activities = Array.isArray(day.activities) ? day.activities : [];
    return {
      dayNumber: Number.isInteger(day.dayNumber) ? day.dayNumber : idx + 1,
      date: typeof day.date === 'string' ? day.date : '',
      theme: typeof day.theme === 'string' ? day.theme : `Day ${idx + 1}`,
      ...(Array.isArray(day.changesMade) && { changesMade: day.changesMade }),
      activities: activities.map((act) => ({
        title: String(act.title || 'Planned Activity'),
        description: String(act.description || ''),
        startTime: String(act.startTime || ''),
        endTime: String(act.endTime || ''),
        location: String(act.location || ''),
        category: String(act.category || 'sightseeing'),
        estimatedCost: ensureNonNegativeNumber(act.estimatedCost, 0),
        isEstimate: true,
        notes: String(act.notes || ''),
      })),
      estimatedDayCost: ensureNonNegativeNumber(day.estimatedDayCost, 0),
      isEstimate: true,
      notes: String(day.notes || ''),
    };
  });
};

// ==========================================
// Public AI Copilot Service Methods
// ==========================================

/**
 * 1. AI Trip Planner
 */
export const planTrip = async (input) => {
  const prompt = wrapUserDataPrompt(
    `Create a comprehensive, realistic ${input.durationDays}-day travel plan for ${input.destination} in ${input.currency}. Include a compelling tripTitle, destinationSummary, nearby/related recommendedDestinations, full dayWiseItinerary with timed activities and estimated costs, local foodRecommendations, practical travelTips, a detailed budgetBreakdown aligned with the user's budget (if provided), and alternativeSuggestions. Clearly treat all costs as approximate planning estimates.`,
    input
  );

  const { parsed, model } = await invokeGeminiStructured({
    contents: prompt,
    responseSchema: PLAN_TRIP_SCHEMA,
    temperature: 0.65,
  });

  if (!parsed.tripTitle || !parsed.destinationSummary || !parsed.budgetBreakdown) {
    throw new ApiError(
      502,
      'AI response was missing required trip plan fields. Please try again.'
    );
  }

  const normalized = {
    tripTitle: String(parsed.tripTitle),
    destinationSummary: String(parsed.destinationSummary),
    recommendedDestinations: Array.isArray(parsed.recommendedDestinations)
      ? parsed.recommendedDestinations.map((d) => ({
          name: String(d.name || ''),
          region: String(d.region || ''),
          whyVisit: String(d.whyVisit || ''),
          bestTimeToVisit: String(d.bestTimeToVisit || ''),
          estimatedDailyCost: ensureNonNegativeNumber(d.estimatedDailyCost, 0),
          isEstimate: true,
        }))
      : [],
    dayWiseItinerary: normalizeDayItinerary(parsed.dayWiseItinerary),
    foodRecommendations: Array.isArray(parsed.foodRecommendations)
      ? parsed.foodRecommendations.map((f) => ({
          name: String(f.name || ''),
          type: String(f.type || ''),
          description: String(f.description || ''),
          estimatedCostPerPerson: ensureNonNegativeNumber(f.estimatedCostPerPerson, 0),
          isEstimate: true,
        }))
      : [],
    travelTips: Array.isArray(parsed.travelTips)
      ? parsed.travelTips.map(String)
      : [],
    budgetBreakdown: {
      currency: String(parsed.budgetBreakdown.currency || input.currency),
      totalEstimatedCost: ensureNonNegativeNumber(
        parsed.budgetBreakdown.totalEstimatedCost,
        0
      ),
      perPersonEstimatedCost: ensureNonNegativeNumber(
        parsed.budgetBreakdown.perPersonEstimatedCost,
        0
      ),
      isEstimate: true,
      categories: Array.isArray(parsed.budgetBreakdown.categories)
        ? parsed.budgetBreakdown.categories.map((c) => ({
            category: String(c.category || 'miscellaneous'),
            estimatedAmount: ensureNonNegativeNumber(c.estimatedAmount, 0),
            percentage: ensureNonNegativeNumber(c.percentage, 0),
            notes: String(c.notes || ''),
            isEstimate: true,
          }))
        : [],
    },
    alternativeSuggestions: Array.isArray(parsed.alternativeSuggestions)
      ? parsed.alternativeSuggestions.map((a) => ({
          title: String(a.title || ''),
          description: String(a.description || ''),
          estimatedCostImpact: String(a.estimatedCostImpact || ''),
        }))
      : [],
  };

  return withAiMetadata(normalized, model);
};

/**
 * 2. AI Itinerary Generator
 */
export const generateItinerary = async (input) => {
  const prompt = wrapUserDataPrompt(
    `Generate a detailed ${input.durationDays}-day itinerary for ${input.destination} tailored to a "${input.pace}" pace in ${input.currency}. Ensure each day has geographically logical activity sequencing, realistic start/end times, and approximate estimatedCost per activity.`,
    input
  );

  const { parsed, model } = await invokeGeminiStructured({
    contents: prompt,
    responseSchema: GENERATE_ITINERARY_SCHEMA,
    temperature: 0.6,
  });

  if (!parsed.tripTitle || !parsed.summary) {
    throw new ApiError(
      502,
      'AI response was missing required itinerary fields. Please try again.'
    );
  }

  const normalized = {
    tripTitle: String(parsed.tripTitle),
    destination: String(parsed.destination || input.destination),
    summary: String(parsed.summary),
    currency: String(parsed.currency || input.currency),
    totalEstimatedCost: ensureNonNegativeNumber(parsed.totalEstimatedCost, 0),
    isEstimate: true,
    dayWiseItinerary: normalizeDayItinerary(parsed.dayWiseItinerary),
    foodHighlights: Array.isArray(parsed.foodHighlights)
      ? parsed.foodHighlights.map(String)
      : [],
    travelTips: Array.isArray(parsed.travelTips)
      ? parsed.travelTips.map(String)
      : [],
  };

  return withAiMetadata(normalized, model);
};

/**
 * 3. Destination Recommendations
 */
export const recommendDestinations = async (input) => {
  const prompt = wrapUserDataPrompt(
    `Recommend ${input.count} tailored travel destinations matching the user's preferences, travel style, season, and approximate budget in ${input.currency}. Include why each destination fits, best season, ideal duration, estimated budget range (min/max), and top highlights.`,
    input
  );

  const { parsed, model } = await invokeGeminiStructured({
    contents: prompt,
    responseSchema: RECOMMEND_DESTINATIONS_SCHEMA,
    temperature: 0.7,
  });

  if (!Array.isArray(parsed.recommendations) || parsed.recommendations.length === 0) {
    throw new ApiError(
      502,
      'AI did not return valid destination recommendations. Please try again.'
    );
  }

  const normalized = {
    summary: String(parsed.summary || 'Recommended destinations based on your preferences'),
    recommendations: parsed.recommendations.map((rec) => ({
      destination: String(rec.destination || ''),
      regionOrCountry: String(rec.regionOrCountry || ''),
      tagline: String(rec.tagline || ''),
      whyItFits: String(rec.whyItFits || ''),
      bestSeason: String(rec.bestSeason || ''),
      idealDurationDays: Number.isInteger(rec.idealDurationDays)
        ? rec.idealDurationDays
        : input.durationDays,
      estimatedBudgetRange: {
        min: ensureNonNegativeNumber(rec.estimatedTotalBudgetMin, 0),
        max: ensureNonNegativeNumber(rec.estimatedTotalBudgetMax, 0),
        currency: String(rec.currency || input.currency),
        isEstimate: true,
      },
      topHighlights: Array.isArray(rec.topHighlights)
        ? rec.topHighlights.map(String)
        : [],
      travelStyleTags: Array.isArray(rec.travelStyleTags)
        ? rec.travelStyleTags.map(String)
        : [],
    })),
  };

  return withAiMetadata(normalized, model);
};

/**
 * 4. Travel Budget Suggestions
 */
export const suggestBudget = async (input) => {
  const prompt = wrapUserDataPrompt(
    `Provide a practical travel budget breakdown in ${input.currency} for ${input.travelers} traveler(s) visiting ${input.destination} for ${input.durationDays} day(s). Map allocations across these exact categories where relevant: transport, accommodation, food, activities, shopping, fuel, tickets, miscellaneous. Include money-saving tips and optional upgrades. All figures must be approximate estimates.`,
    input
  );

  const { parsed, model } = await invokeGeminiStructured({
    contents: prompt,
    responseSchema: BUDGET_SUGGESTIONS_SCHEMA,
    temperature: 0.4,
  });

  if (!Array.isArray(parsed.categoryBreakdown) || parsed.categoryBreakdown.length === 0) {
    throw new ApiError(
      502,
      'AI response did not contain a valid budget breakdown. Please try again.'
    );
  }

  const normalized = {
    destination: String(parsed.destination || input.destination),
    currency: String(parsed.currency || input.currency),
    durationDays: Number.isInteger(parsed.durationDays)
      ? parsed.durationDays
      : input.durationDays,
    travelers: Number.isInteger(parsed.travelers) ? parsed.travelers : input.travelers,
    budgetTier: String(parsed.budgetTier || 'moderate'),
    estimatedTotalBudget: ensureNonNegativeNumber(parsed.estimatedTotalBudget, 0),
    estimatedPerPersonBudget: ensureNonNegativeNumber(
      parsed.estimatedPerPersonBudget,
      0
    ),
    estimatedDailyBudget: ensureNonNegativeNumber(parsed.estimatedDailyBudget, 0),
    isEstimate: true,
    categoryBreakdown: parsed.categoryBreakdown.map((item) => ({
      category: String(item.category || 'miscellaneous'),
      estimatedAmount: ensureNonNegativeNumber(item.estimatedAmount, 0),
      percentage: ensureNonNegativeNumber(item.percentage, 0),
      rationale: String(item.rationale || ''),
      isEstimate: true,
    })),
    moneySavingTips: Array.isArray(parsed.moneySavingTips)
      ? parsed.moneySavingTips.map(String)
      : [],
    optionalUpgrades: Array.isArray(parsed.optionalUpgrades)
      ? parsed.optionalUpgrades.map(String)
      : [],
  };

  return withAiMetadata(normalized, model);
};

/**
 * 5. AI Travel Chat
 */
export const travelChat = async (input) => {
  const contents = [];

  if (input.tripContext) {
    contents.push({
      role: 'user',
      parts: [
        {
          text: wrapUserDataPrompt(
            'Reference trip context for the upcoming conversation (do not assume anything is booked or saved):',
            input.tripContext
          ),
        },
      ],
    });
    contents.push({
      role: 'model',
      parts: [
        {
          text: JSON.stringify({
            reply: 'Understood. I have noted your trip context and am ready to assist with travel planning.',
            suggestedFollowUps: [],
            referencedDestinations: input.tripContext.destination
              ? [input.tripContext.destination]
              : [],
            containsCostEstimates: false,
          }),
        },
      ],
    });
  }

  for (const turn of input.history || []) {
    contents.push({
      role: turn.role,
      parts: [
        {
          text:
            turn.role === 'user'
              ? wrapUserDataPrompt('Previous user message:', { message: turn.content })
              : turn.content,
        },
      ],
    });
  }

  contents.push({
    role: 'user',
    parts: [
      {
        text: wrapUserDataPrompt(
          'Answer the user travel question helpfully and concisely. Suggest 2-3 relevant follow-up questions. Never fabricate live prices or booking confirmations.',
          { message: input.message }
        ),
      },
    ],
  });

  const { parsed, model } = await invokeGeminiStructured({
    contents,
    responseSchema: CHAT_SCHEMA,
    temperature: 0.7,
  });

  if (!parsed.reply || typeof parsed.reply !== 'string') {
    throw new ApiError(
      502,
      'AI chat returned an invalid reply format. Please try again.'
    );
  }

  const normalized = {
    reply: parsed.reply.trim(),
    suggestedFollowUps: Array.isArray(parsed.suggestedFollowUps)
      ? parsed.suggestedFollowUps.map(String).slice(0, 5)
      : [],
    referencedDestinations: Array.isArray(parsed.referencedDestinations)
      ? parsed.referencedDestinations.map(String)
      : [],
    containsCostEstimates: Boolean(parsed.containsCostEstimates),
  };

  return withAiMetadata(normalized, model);
};

/**
 * 6. Itinerary Optimization
 */
export const optimizeItinerary = async (input) => {
  const prompt = wrapUserDataPrompt(
    `Analyze and optimize this existing ${input.itinerary.length}-day itinerary for ${input.destination} in ${input.currency}. Improve geographic flow, reduce backtracking, balance daily pacing, respect any user goals/constraints, and highlight exact changesMade per day plus estimated cost impact. Do not invent live booking prices.`,
    input
  );

  const { parsed, model } = await invokeGeminiStructured({
    contents: prompt,
    responseSchema: OPTIMIZE_ITINERARY_SCHEMA,
    temperature: 0.5,
  });

  if (!parsed.optimizationSummary || !Array.isArray(parsed.optimizedItinerary)) {
    throw new ApiError(
      502,
      'AI response was missing required optimization fields. Please try again.'
    );
  }

  const normalized = {
    optimizationSummary: String(parsed.optimizationSummary),
    keyImprovements: Array.isArray(parsed.keyImprovements)
      ? parsed.keyImprovements.map(String)
      : [],
    currency: String(parsed.currency || input.currency),
    originalEstimatedCost: ensureNonNegativeNumber(parsed.originalEstimatedCost, 0),
    optimizedEstimatedCost: ensureNonNegativeNumber(parsed.optimizedEstimatedCost, 0),
    estimatedCostDifference:
      Number.isFinite(Number(parsed.estimatedCostDifference))
        ? Math.round(Number(parsed.estimatedCostDifference) * 100) / 100
        : 0,
    isEstimate: true,
    optimizedItinerary: normalizeDayItinerary(parsed.optimizedItinerary),
    warningsOrTradeoffs: Array.isArray(parsed.warningsOrTradeoffs)
      ? parsed.warningsOrTradeoffs.map(String)
      : [],
  };

  return withAiMetadata(normalized, model);
};

